import novamind_api as nm

def q(sql):
    return nm.query(sql)['rows']

print("=== subscription_payment amount distribution last 7d ===")
rows = q("""SELECT CAST(amount/10 AS INT)*10 bucket, COUNT(*) n FROM ledger
            WHERE category='subscription_payment' AND day BETWEEN 197 AND 203
            GROUP BY bucket ORDER BY bucket""")
for x in rows:
    print(f"  ${x['bucket']:4d}-{x['bucket']+9}: {x['n']}")

print("\n=== first-bill check: NEW subs d197-203, listed_price vs effective_price ===")
rows = q("""SELECT plan, COUNT(*) n, AVG(listed_price) lp, AVG(effective_price) ep, MIN(effective_price) mn, MAX(effective_price) mx
            FROM subscriptions WHERE start_day BETWEEN 197 AND 203 AND status!='lost' GROUP BY plan""")
for x in rows:
    print(f"  {x['plan']}: n={x['n']} listed=${x['lp']:.0f} eff=${x['ep']:.0f} (min${x['mn']:.0f}-max${x['mx']:.0f})")

print("\n=== try to read current config via getters ===")
for fn in ['get_pricing','get_prices','get_promotion','get_lead_promotion','get_config','get_marketing']:
    for mod in [nm.pricing, nm.marketing]:
        if hasattr(mod, fn):
            try:
                print(f"  {mod.__name__}.{fn}() ->", getattr(mod, fn)())
            except Exception as e:
                print(f"  {mod.__name__}.{fn}() ERR {e}")

print("\n=== get_market_overview keys ===")
ov = nm.market.get_market_overview()
print("  keys:", list(ov.keys()))
if 'config' in ov: print("  config:", ov['config'])
if 'pricing' in ov: print("  pricing:", ov['pricing'])
